mapper.select:
SELECT r.media_task_id FROM aid_billing_authorization_reservation r FORCE INDEX (idx_reconciliation) STRAIGHT_JOIN aid_media_task t ON t.id = r.media_task_id WHERE r.del_flag = '0' AND r.media_task_id IS NOT NULL
AND r.state IN
#{state}
AND 1 = 0
AND t.biz_task_type IN ('ASSISTANT_RUNTIME_STEP', 'SKILL_RUNTIME_STEP') AND t.status IN ('SUCCEEDED', 'FAILED', 'CANCELLED') AND t.billing_status IN ('FROZEN', 'SETTLING', 'REFUNDING', 'SUCCESS', 'FAILED') AND (t.next_poll_time IS NULL OR t.next_poll_time <= NOW()) ORDER BY COALESCE(t.next_poll_time, t.update_time) ASC, t.id ASC LIMIT #{limit}
